"""Holt einen VDO.Ninja-Stream per WebRTC direkt in Python.

VDO.Ninja ist kein abrufbarer Videostream, sondern WebRTC zwischen zwei Peers. Dieses Modul
spricht dasselbe Protokoll wie die VDO.Ninja-Webseite: Anmeldung am Handshake-Server, Bitte um
den Stream, Antwort auf das Angebot. Die Bilder landen ohne Umweg über einen Browser im Kamera-Thread.
"""

import asyncio
import hashlib
import json
import os
import re
import threading
from collections.abc import Callable
from dataclasses import dataclass
from urllib.parse import parse_qsl, urlsplit

import numpy as np
import websockets
from aiortc import (
    MediaStreamTrack,
    RTCConfiguration,
    RTCIceServer,
    RTCPeerConnection,
    RTCSessionDescription,
)
from aiortc.mediastreams import MediaStreamError
from aiortc.sdp import candidate_from_sdp
from cryptography.hazmat.primitives import padding
from cryptography.hazmat.primitives.ciphers import Cipher, algorithms, modes

SIGNALING = "wss://wss.vdo.ninja:443"
DEFAULT_PASSWORD = "someEncryptionKey123"
DEFAULT_SALT = "vdo.ninja"
PLAY_RETRY_S = 4.0
CONNECT_TIMEOUT_S = 30.0
RECONNECT_S = 2.0
ICE_SERVERS = ["stun:stun.l.google.com:19302", "stun:stun.cloudflare.com:3478"]

_LINK = re.compile(r"vdo\.ninja|versus\.cam|invite\.cam", re.IGNORECASE)


class NinjaError(Exception):
    """Fehler mit einer Meldung, die direkt beim Bediener landen darf."""


def looks_like_ninja(link: str) -> bool:
    return bool(_LINK.search(link))


@dataclass(frozen=True)
class Target:
    stream_id: str
    key: bytes | None


def parse(link: str) -> Target:
    """Liest Stream-Name und Passwort aus einem normalen View-Link."""
    text = link.strip()
    if not text:
        raise NinjaError("Kein VDO.Ninja-Link angegeben.")
    url = urlsplit(text if "://" in text else f"https://{text}")
    params = dict(parse_qsl(url.query, keep_blank_values=True))
    # VDO.Ninja packt die Angaben teils hinter ein Doppelkreuz.
    for name, value in parse_qsl(url.fragment, keep_blank_values=True):
        params.setdefault(name, value)

    view = params.get("view") or params.get("v") or params.get("scene")
    if not view:
        raise NinjaError("Im VDO.Ninja-Link fehlt view=… mit dem Namen des Streams.")

    raw = next((params[k] for k in ("password", "pass", "p") if k in params), None)
    password = DEFAULT_PASSWORD if raw is None else raw.strip()
    if password in ("", "false", "0"):
        return Target(view, None)

    labels = (url.hostname or "").split(".")
    salt = ".".join(labels[-2:]) if len(labels) >= 2 else DEFAULT_SALT
    digest = hashlib.sha256((password + salt).encode()).digest()
    # VDO.Ninja hängt die ersten sechs Hex-Zeichen an, damit fremde Passwörter einen anderen Stream sehen.
    return Target(view + digest.hex()[:6], digest)


def encrypt(key: bytes, text: str) -> tuple[str, str]:
    vector = os.urandom(16)
    padder = padding.PKCS7(128).padder()
    data = padder.update(text.encode()) + padder.finalize()
    encryptor = Cipher(algorithms.AES(key), modes.CBC(vector)).encryptor()
    return (encryptor.update(data) + encryptor.finalize()).hex(), vector.hex()


def decrypt(key: bytes, data: str, vector: str) -> str:
    decryptor = Cipher(algorithms.AES(key), modes.CBC(bytes.fromhex(vector))).decryptor()
    padded = decryptor.update(bytes.fromhex(data)) + decryptor.finalize()
    unpadder = padding.PKCS7(128).unpadder()
    return (unpadder.update(padded) + unpadder.finalize()).decode()


def receive(
    link: str,
    stop: threading.Event,
    on_frame: Callable[[np.ndarray], None],
    on_status: Callable[[str], None],
) -> None:
    """Blockiert, bis ``stop`` gesetzt ist, und baut abgerissene Verbindungen neu auf."""
    target = parse(link)
    asyncio.run(_loop(target, stop, on_frame, on_status))


async def _loop(
    target: Target,
    stop: threading.Event,
    on_frame: Callable[[np.ndarray], None],
    on_status: Callable[[str], None],
) -> None:
    stopped = asyncio.ensure_future(asyncio.to_thread(stop.wait))
    while not stopped.done():
        on_status("Warte auf den VDO.Ninja-Stream …")
        session = _Session(target, on_frame)
        run = asyncio.ensure_future(session.run())
        await asyncio.wait({run, stopped}, return_when=asyncio.FIRST_COMPLETED)
        run.cancel()
        try:
            await run
        except asyncio.CancelledError:
            pass
        except NinjaError as exc:
            on_status(str(exc))
        except Exception as exc:  # noqa: BLE001
            on_status(f"VDO.Ninja-Fehler: {exc}. Neuer Versuch läuft.")
        await session.close()
        if not stopped.done():
            await asyncio.wait({stopped}, timeout=RECONNECT_S)


class _Session:
    """Genau eine Verbindung zu genau einem Stream."""

    def __init__(self, target: Target, on_frame: Callable[[np.ndarray], None]):
        self._target = target
        self._on_frame = on_frame
        self._pc = RTCPeerConnection(RTCConfiguration([RTCIceServer(urls=u) for u in ICE_SERVERS]))
        self._ws: websockets.ClientConnection | None = None
        self._peer_uuid: str | None = None
        self._session_id: str | None = None
        self._waiting: list[dict] = []
        self._remote_ready = False
        self._video = asyncio.Event()
        self._ended = asyncio.Event()
        self._failure: str | None = None
        self._tasks: set[asyncio.Task] = set()
        self._pc.on("track", self._on_track)
        self._pc.on("datachannel", self._on_channel)
        self._pc.on("connectionstatechange", self._on_state)

    async def run(self) -> None:
        async with websockets.connect(SIGNALING, max_size=None) as ws:
            self._ws = ws
            self._spawn(self._read())
            loop = asyncio.get_running_loop()
            deadline = loop.time() + CONNECT_TIMEOUT_S
            # Die Gegenseite ist vielleicht noch nicht online, daher regelmäßig nachfragen.
            while not self._video.is_set() and not self._ended.is_set():
                if loop.time() > deadline:
                    raise NinjaError("Der VDO.Ninja-Stream meldet sich nicht. Läuft die Gegenseite gerade?")
                await self._send({"request": "play", "streamID": self._target.stream_id})
                await _wait_any(self._video, self._ended, PLAY_RETRY_S)
            await self._ended.wait()
        raise NinjaError(self._failure or "VDO.Ninja-Stream ist abgerissen. Neuer Versuch läuft.")

    async def close(self) -> None:
        for task in list(self._tasks):
            task.cancel()
        await self._pc.close()

    def _fail(self, message: str) -> None:
        self._failure = self._failure or message
        self._ended.set()

    def _spawn(self, coro) -> None:
        task = asyncio.ensure_future(coro)
        self._tasks.add(task)
        task.add_done_callback(self._tasks.discard)

    # ------------------------------------------------------------------ Signaling
    async def _send(self, payload: dict) -> None:
        if self._ws is None:
            return
        try:
            await self._ws.send(json.dumps(payload))
        except websockets.ConnectionClosed:
            pass

    async def _send_secure(self, payload: dict) -> None:
        key = self._target.key
        if key is not None:
            payload = dict(payload)
            for field in ("description", "candidate", "candidates"):
                if field in payload:
                    payload[field], payload["vector"] = encrypt(key, json.dumps(payload[field]))
        await self._send(payload)

    async def _read(self) -> None:
        assert self._ws is not None
        try:
            async for raw in self._ws:
                if not isinstance(raw, str):
                    continue
                try:
                    msg = json.loads(raw)
                except ValueError:
                    continue
                if isinstance(msg, dict):
                    await self._handle(msg)
        except websockets.ConnectionClosed:
            pass
        except NinjaError as exc:
            self._fail(str(exc))
            return
        except Exception as exc:  # noqa: BLE001
            self._fail(f"VDO.Ninja-Fehler: {exc}. Neuer Versuch läuft.")
            return
        # Steht das Video schon, läuft es Peer-zu-Peer weiter und braucht den Server nicht mehr.
        if not self._video.is_set():
            self._fail("Der VDO.Ninja-Server hat die Verbindung beendet. Neuer Versuch läuft.")

    async def _handle(self, msg: dict) -> None:
        """Nachrichten kommen über den Handshake-Server und über den Datenkanal."""
        if isinstance(msg.get("UUID"), str):
            self._peer_uuid = msg["UUID"]
        if isinstance(msg.get("session"), str):
            self._session_id = msg["session"]

        if "description" in msg:
            description = self._unseal(msg, "description")
            if isinstance(description, dict) and description.get("type") == "offer":
                await self._answer(description)
            return

        field = "candidates" if "candidates" in msg else "candidate" if "candidate" in msg else None
        if field:
            value = self._unseal(msg, field)
            for entry in value if isinstance(value, list) else [value]:
                if isinstance(entry, dict) and entry.get("candidate"):
                    await self._add_candidate(entry)

    def _unseal(self, msg: dict, field: str):
        value = msg[field]
        if not isinstance(value, str):
            return value
        key = self._target.key
        if key is None or not isinstance(msg.get("vector"), str):
            return None
        try:
            return json.loads(decrypt(key, value, msg["vector"]))
        except ValueError as exc:
            raise NinjaError("Das Passwort im VDO.Ninja-Link passt nicht zum Stream.") from exc

    def _envelope(self, payload: dict) -> dict:
        # Der Server verteilt Nachrichten anhand von UUID und Sitzung.
        if self._peer_uuid:
            payload["UUID"] = self._peer_uuid
        if self._session_id:
            payload["session"] = self._session_id
        return payload

    # --------------------------------------------------------------------- WebRTC
    async def _answer(self, offer: dict) -> None:
        await self._pc.setRemoteDescription(RTCSessionDescription(sdp=offer["sdp"], type="offer"))
        self._remote_ready = True
        waiting, self._waiting = self._waiting, []
        for entry in waiting:
            await self._apply_candidate(entry)
        await self._pc.setLocalDescription(await self._pc.createAnswer())
        local = self._pc.localDescription
        # aiortc sammelt alle eigenen Kandidaten vorab ins SDP, ein Nachreichen entfällt daher.
        await self._send_secure(self._envelope({"description": {"type": local.type, "sdp": local.sdp}}))

    async def _add_candidate(self, entry: dict) -> None:
        if not self._remote_ready:
            self._waiting.append(entry)
            return
        await self._apply_candidate(entry)

    async def _apply_candidate(self, entry: dict) -> None:
        text = str(entry["candidate"])
        try:
            candidate = candidate_from_sdp(text.split(":", 1)[1] if text.startswith("candidate:") else text)
            candidate.sdpMid = entry.get("sdpMid")
            candidate.sdpMLineIndex = entry.get("sdpMLineIndex")
            await self._pc.addIceCandidate(candidate)
        except Exception:  # noqa: BLE001
            # Einzelne unbrauchbare Kandidaten sind normal, die übrigen reichen meist.
            pass

    def _on_track(self, track: MediaStreamTrack) -> None:
        self._spawn(self._pump(track) if track.kind == "video" else _drain(track))

    async def _pump(self, track: MediaStreamTrack) -> None:
        try:
            while True:
                frame = await track.recv()
                self._on_frame(frame.to_ndarray(format="bgr24"))
                self._video.set()
        except MediaStreamError:
            self._fail("VDO.Ninja-Stream ist abgerissen. Neuer Versuch läuft.")

    def _on_channel(self, channel) -> None:
        def hello() -> None:
            channel.send(json.dumps({"video": True, "audio": False, "info": True}))

        def on_message(data) -> None:
            if not isinstance(data, str):
                return
            try:
                msg = json.loads(data)
            except ValueError:
                # Der Kanal überträgt auch Dinge, die hier niemanden interessieren.
                return
            if isinstance(msg, dict):
                self._spawn(self._handle_safe(msg))

        channel.on("message", on_message)
        if channel.readyState == "open":
            hello()
        else:
            channel.on("open", hello)

    async def _handle_safe(self, msg: dict) -> None:
        try:
            await self._handle(msg)
        except NinjaError as exc:
            self._fail(str(exc))

    async def _on_state(self) -> None:
        if self._pc.connectionState in ("failed", "closed"):
            self._fail("WebRTC-Verbindung zu VDO.Ninja verloren. Neuer Versuch läuft.")


async def _drain(track: MediaStreamTrack) -> None:
    # Ungelesene Spuren füllen sonst endlos ihre Warteschlange.
    try:
        while True:
            await track.recv()
    except MediaStreamError:
        pass


async def _wait_any(a: asyncio.Event, b: asyncio.Event, timeout: float) -> None:
    waiters = {asyncio.ensure_future(a.wait()), asyncio.ensure_future(b.wait())}
    _, pending = await asyncio.wait(waiters, timeout=timeout, return_when=asyncio.FIRST_COMPLETED)
    for task in pending:
        task.cancel()
